import { serve } from 'https://deno.land/std@0.208.0/http/server.ts';
import { createClient, SupabaseClient } from 'https://esm.sh/@supabase/supabase-js@2.45.4';

// ---- _shared/supabase.ts ---------------------------------------------------------------------
function getServiceClient(): SupabaseClient {
  return createClient(
    Deno.env.get('SUPABASE_URL') ?? '',
    Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '',
  );
}

/**
 * Connection string for functions that talk raw Postgres (deno-postgres / pg).
 * At 1000+ tenants you MUST go through Supavisor in TRANSACTION mode (port 6543)
 * so a burst of concurrent functions doesn't exhaust backend connections.
 * Set SUPABASE_DB_POOL_URL to the "Transaction pooler" URI from
 * Dashboard -> Project Settings -> Database. Falls back to the direct URL.
 * RLS in v2 reads the JWT (no session GUCs) so transaction pooling is safe.
 */
function getPooledConnectionString(): string {
  return (
    Deno.env.get('SUPABASE_DB_POOL_URL') ??
    Deno.env.get('SUPABASE_DB_URL') ??
    ''
  );
}

function corsHeaders(origin = '*') {
  return {
    'Access-Control-Allow-Origin': origin,
    'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-tenant-id, x-environment',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
  };
}

function jsonResponse(data: unknown, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { ...corsHeaders(), 'Content-Type': 'application/json' },
  });
}

function errorResponse(message: string, status = 400) {
  return jsonResponse({ error: message }, status);
}

// resolveTenantContext (trusted X-Tenant-Id) and validateApiKey (prefix-only check) were
// removed in Phase 0 (SEC-02 / SEC-04). Use _shared/auth.ts for signed-in users, or
// _shared/ingest-auth.ts (API keys via verify_api_key, site keys via resolve_ingest_site).

// ---- _shared/auth.ts ---------------------------------
// Shared caller authentication for edge functions (Phase 0, SEC-01).
//
// Rule (docs/cpo/09-security-baseline.md §2): a function derives tenant access
// from a VERIFIED credential, never from a header or body. For calls made by a
// signed-in app user, the safest pattern is to act AS that user: queries run
// through a client carrying the user's JWT, so Postgres RLS enforces tenant
// isolation even if function code has a bug. Use the service role only after
// authentication, and only for work RLS can't express.


class AuthError extends Error {
  status: number;
  constructor(status: number, message: string) {
    super(message);
    this.status = status;
  }
}

type AuthedUser = {
  userId: string;
  email: string | null;
  /** Client that runs every query as the caller — RLS applies. */
  db: SupabaseClient;
};

const AUTH_UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

function requireEnv(name: string): string {
  const v = Deno.env.get(name);
  if (!v) throw new AuthError(500, `Server misconfigured: ${name} is not set`);
  return v;
}

/** Verify the bearer token belongs to a real signed-in user (not the anon key). */
async function authenticateUser(req: Request): Promise<AuthedUser> {
  const header = req.headers.get('authorization') ?? '';
  const token = header.startsWith('Bearer ') ? header.slice(7).trim() : '';
  if (!token) throw new AuthError(401, 'Not signed in');

  const db = createClient(requireEnv('SUPABASE_URL'), requireEnv('SUPABASE_ANON_KEY'), {
    global: { headers: { Authorization: `Bearer ${token}` } },
    auth: { persistSession: false, autoRefreshToken: false },
  });

  // getUser validates signature + expiry with Auth; the anon key has no user and fails here.
  const { data, error } = await db.auth.getUser(token);
  if (error || !data?.user) throw new AuthError(401, 'Session is invalid or expired');

  return { userId: data.user.id, email: data.user.email ?? null, db };
}

/** Confirm the caller is an active member of the tenant (checked by the database as the caller). */
async function requireTenantMember(user: AuthedUser, tenantId: unknown): Promise<string> {
  if (typeof tenantId !== 'string' || !AUTH_UUID_RE.test(tenantId)) throw new AuthError(400, 'tenant_id must be a UUID');
  const { data, error } = await user.db.rpc('user_has_tenant_access', { p_tenant_id: tenantId });
  if (error) {
    console.error('tenant membership check failed', error.message);
    throw new AuthError(500, 'Could not verify tenant access');
  }
  if (data !== true) throw new AuthError(403, 'No access to this tenant');
  return tenantId.toLowerCase();
}

/** Tenant named by the caller (membership verified), or the caller's own active membership. */
async function resolveTenant(user: AuthedUser, tenantId: unknown): Promise<string> {
  if (tenantId !== undefined && tenantId !== null && tenantId !== '') return requireTenantMember(user, tenantId);
  const { data, error } = await user.db.from('tenant_users').select('tenant_id')
    .eq('user_id', user.userId).eq('status', 'active').order('created_at').limit(1);
  if (error) throw new AuthError(500, 'Could not resolve your workspace');
  const t = data?.[0]?.tenant_id as string | undefined;
  if (!t) throw new AuthError(403, 'You are not a member of any workspace');
  return t;
}

/** Throws 403 unless the caller holds `permission` in the tenant (tenant admins hold all). */
async function requirePermission(user: AuthedUser, tenantId: string, permission: string, label?: string): Promise<void> {
  const { data, error } = await user.db.rpc('user_has_permission', { p_tenant_id: tenantId, p_permission: permission });
  if (error) throw new AuthError(500, 'Could not verify permissions');
  if (data !== true) throw new AuthError(403, `You need the "${label ?? permission}" permission for this`);
}

// ---- _shared/ingest-auth.ts ------------------------------------------------------------------
// Authentication for PUBLIC ingest endpoints (Phase 0, SEC-02).
//
// Two credential types — tenant/environment always come from the credential, never the request:
//   • Secret API key (server-to-server): `x-api-key: mk_…` or `Authorization: Bearer mk_…`.
//     Verified by public.verify_api_key() (bcrypt). Must carry the required scope.
//   • Site key (browser SDKs): body `site_id` + `write_key` (public by design, like a
//     Segment write key). Verified by public.resolve_ingest_site(): key, site status and
//     the browser Origin against the site's domain / allowed_origins.
//
// Because a site key is public, it can be copied and replayed from a script. Defences:
// per-site + per-IP rate limits here (per isolate — a backstop), frequency caps at send
// time (Wave 1 guardrails), and identity verification for identified users (SEC-13).


type IngestContext = {
  tenantId: string;
  environment: string;
  via: 'api_key' | 'site_key';
  siteId?: string;
  siteUuid?: string;
};

/** Read the secret API key if one was sent. JWTs (anon/user tokens) are ignored here. */
function readApiKey(req: Request): string | null {
  const header = req.headers.get('x-api-key')?.trim();
  if (header) return header;
  const auth = req.headers.get('authorization') ?? '';
  const bearer = auth.startsWith('Bearer ') ? auth.slice(7).trim() : '';
  // Supabase JWTs have three dot-separated parts; Marbee API keys don't.
  if (bearer && bearer.split('.').length !== 3) return bearer;
  return null;
}

async function authenticateApiKey(db: SupabaseClient, rawKey: string, scope: string): Promise<IngestContext> {
  const { data, error } = await db.rpc('verify_api_key', { p_raw_key: rawKey });
  if (error) {
    console.error('verify_api_key failed', error.message);
    throw new AuthError(500, 'Could not verify API key');
  }
  const row = Array.isArray(data) ? data[0] : null;
  if (!row) throw new AuthError(401, 'Invalid or revoked API key');
  const scopes: string[] = row.scopes ?? [];
  if (!scopes.includes(scope) && !scopes.includes('*')) throw new AuthError(403, `API key is missing the ${scope} scope`);
  return { tenantId: row.tenant_id, environment: row.environment ?? 'production', via: 'api_key' };
}

async function authenticateSiteKey(
  db: SupabaseClient,
  siteId: unknown,
  writeKey: unknown,
  origin: string | null,
): Promise<IngestContext> {
  if (typeof siteId !== 'string' || typeof writeKey !== 'string') {
    throw new AuthError(401, 'site_id and write_key are required');
  }
  const { data, error } = await db.rpc('resolve_ingest_site', {
    p_site_id: siteId, p_write_key: writeKey, p_origin: origin,
  });
  if (error) {
    console.error('resolve_ingest_site failed', error.message);
    throw new AuthError(500, 'Could not verify site key');
  }
  const r = data as { ok: boolean; reason?: string; tenant_id?: string; environment?: string; site_id?: string; site_uuid?: string };
  if (!r?.ok) {
    const status = r?.reason === 'invalid_key' ? 401 : 403;
    const message = r?.reason === 'origin_not_allowed'
      ? 'This website is not allowed to use this site key'
      : r?.reason?.startsWith('site_') ? 'Site is not active' : 'Invalid site key';
    throw new AuthError(status, message);
  }
  return { tenantId: r.tenant_id!, environment: r.environment ?? 'production', via: 'site_key', siteId: r.site_id, siteUuid: r.site_uuid };
}

/** API key if present, otherwise site key from the parsed body. */
async function authenticateIngest(
  req: Request,
  db: SupabaseClient,
  body: Record<string, unknown> | null,
  scope: string,
): Promise<IngestContext> {
  const apiKey = readApiKey(req);
  if (apiKey) return authenticateApiKey(db, apiKey, scope);
  return authenticateSiteKey(db, body?.site_id, body?.write_key, req.headers.get('origin'));
}

// --------------------------------------------------------------------------------------
// Rate limit — fixed window per isolate. A backstop against floods, not a billing meter.
// --------------------------------------------------------------------------------------
const windows = new Map<string, { start: number; count: number }>();

function rateLimited(key: string, max: number, windowMs = 60_000): boolean {
  const now = Date.now();
  const w = windows.get(key);
  if (!w || now - w.start >= windowMs) {
    windows.set(key, { start: now, count: 1 });
    if (windows.size > 10_000) windows.clear(); // bound memory
    return false;
  }
  w.count += 1;
  return w.count > max;
}

function clientIp(req: Request): string {
  return req.headers.get('cf-connecting-ip')
    ?? req.headers.get('x-forwarded-for')?.split(',')[0]?.trim()
    ?? 'unknown';
}

/** Reject oversized bodies before parsing (Content-Length when present). */
function tooLarge(req: Request, maxBytes: number): boolean {
  const len = Number(req.headers.get('content-length') ?? 0);
  return Number.isFinite(len) && len > maxBytes;
}

// ---- _shared/net-guard.ts --------------------------------------------------------------------
// Outbound request guard against SSRF (Phase 0 · SEC-08).
//
// Any edge function that fetches a URL supplied by a tenant (connector tests, outbound
// webhooks, API lookups) must call assertPublicHttpUrl() first and fetch with
// redirect: 'manual'. Otherwise a tenant could make Marbee's servers reach internal
// services — e.g. the cloud metadata endpoint 169.254.169.254, localhost admin ports,
// or other hosts inside the provider's network.

class BlockedUrlError extends Error {}

const BLOCKED_HOSTNAMES = new Set(['localhost', 'metadata', 'metadata.google.internal', 'instance-data']);
const BLOCKED_SUFFIXES = ['.localhost', '.local', '.internal', '.lan', '.home.arpa', '.intranet', '.corp'];

function ipv4ToInt(ip: string): number | null {
  const parts = ip.split('.');
  if (parts.length !== 4) return null;
  let n = 0;
  for (const p of parts) {
    if (!/^\d{1,3}$/.test(p)) return null;
    const v = Number(p);
    if (v > 255) return null;
    n = n * 256 + v;
  }
  return n >>> 0;
}

function inCidr(ip: number, base: string, bits: number): boolean {
  const b = ipv4ToInt(base)!;
  const mask = bits === 0 ? 0 : (0xffffffff << (32 - bits)) >>> 0;
  return (ip & mask) === (b & mask);
}

const PRIVATE_V4: Array<[string, number]> = [
  ['0.0.0.0', 8], ['10.0.0.0', 8], ['100.64.0.0', 10], ['127.0.0.0', 8], ['169.254.0.0', 16],
  ['172.16.0.0', 12], ['192.0.0.0', 24], ['192.0.2.0', 24], ['192.168.0.0', 16], ['198.18.0.0', 15],
  ['198.51.100.0', 24], ['203.0.113.0', 24], ['224.0.0.0', 4], ['240.0.0.0', 4],
];

/** True for loopback, private, link-local (incl. cloud metadata), CGNAT, multicast, reserved. */
function isPrivateAddress(addr: string): boolean {
  const a = addr.trim().toLowerCase().replace(/^\[|\]$/g, '');
  const v4 = ipv4ToInt(a);
  if (v4 !== null) return PRIVATE_V4.some(([base, bits]) => inCidr(v4, base, bits));
  if (!a.includes(':')) return false;
  // IPv6
  if (a === '::' || a === '::1') return true;
  // IPv4-mapped (::ffff:a.b.c.d) — URL parsing normalises it to hex (::ffff:7f00:1).
  const mapped = a.match(/^::ffff:(\d+\.\d+\.\d+\.\d+)$/);
  if (mapped) return isPrivateAddress(mapped[1]);
  const mappedHex = a.match(/^::ffff:([0-9a-f]{1,4}):([0-9a-f]{1,4})$/);
  if (mappedHex) {
    const hi = parseInt(mappedHex[1], 16), lo = parseInt(mappedHex[2], 16);
    return isPrivateAddress(`${hi >> 8}.${hi & 255}.${lo >> 8}.${lo & 255}`);
  }
  // IPv4-compatible / NAT64 forms embedding an IPv4 address: treat as private to be safe.
  if (/^::(ffff:0:)?[0-9a-f]{1,4}:[0-9a-f]{1,4}$/.test(a) || a.startsWith('64:ff9b:')) return true;
  const first = parseInt(a.split(':')[0] || '0', 16);
  if ((first & 0xfe00) === 0xfc00) return true; // fc00::/7 unique local
  if ((first & 0xffc0) === 0xfe80) return true; // fe80::/10 link-local
  if ((first & 0xff00) === 0xff00) return true; // ff00::/8 multicast
  return false;
}

function isIpLiteral(host: string): boolean {
  return ipv4ToInt(host) !== null || host.includes(':');
}

/**
 * Throws BlockedUrlError unless `raw` is an http(s) URL to a public host.
 * Resolves the hostname (when the runtime allows) and rejects if ANY address is private,
 * which also stops "public name → internal IP" tricks at check time.
 */
async function assertPublicHttpUrl(raw: string): Promise<URL> {
  let url: URL;
  try {
    url = new URL(raw);
  } catch {
    throw new BlockedUrlError('Invalid URL');
  }
  if (url.protocol !== 'https:' && url.protocol !== 'http:') throw new BlockedUrlError('Only http(s) URLs are allowed');
  if (url.username || url.password) throw new BlockedUrlError('URLs with embedded credentials are not allowed');

  const host = url.hostname.toLowerCase().replace(/^\[|\]$/g, '').replace(/\.$/, '');
  if (!host) throw new BlockedUrlError('URL has no host');
  if (BLOCKED_HOSTNAMES.has(host) || BLOCKED_SUFFIXES.some((s) => host.endsWith(s))) {
    throw new BlockedUrlError('Internal hostnames are not allowed');
  }
  if (isIpLiteral(host)) {
    if (isPrivateAddress(host)) throw new BlockedUrlError('Private or internal IP addresses are not allowed');
    return url;
  }
  if (!host.includes('.')) throw new BlockedUrlError('Single-label hostnames are not allowed');

  // deno-lint-ignore no-explicit-any
  const resolve = (globalThis as any).Deno?.resolveDns as undefined | ((h: string, t: string) => Promise<string[]>);
  if (resolve) {
    const addrs: string[] = [];
    let notFound = 0;
    let lookupUnavailable = 0;
    for (const type of ['A', 'AAAA']) {
      try {
        addrs.push(...await resolve(host, type));
      } catch (e) {
        // "NotFound" = the name genuinely has no such records. Anything else (permission
        // denied, resolver unsupported/timeout) means DNS checks aren't possible here.
        if (e instanceof Error && /NotFound|NXDOMAIN|no data|not found/i.test(`${e.name} ${e.message}`)) notFound += 1;
        else lookupUnavailable += 1;
      }
    }
    if (addrs.length > 0) {
      if (addrs.some(isPrivateAddress)) throw new BlockedUrlError('Hostname resolves to a private or internal address');
    } else if (notFound === 2) {
      throw new BlockedUrlError('Hostname does not resolve');
    } else if (lookupUnavailable > 0) {
      // Degrade safely: hostname + IP-literal checks above still apply; never block every
      // legitimate connector just because this runtime can't do DNS lookups.
      console.warn('net-guard: DNS lookup unavailable; relying on hostname/IP checks for', host);
    }
  }
  return url;
}

// ---- connector-test/index.ts -----------------------------------------------------------------
// connector-test — "Test connection" for connectors and connector links.
//
// SEC-08 (Phase 0): previously had no authentication at all, so anyone could make
// Marbee's servers fetch arbitrary URLs (SSRF — e.g. the cloud metadata service), and
// test_link read ANY tenant's connectors with the service role. Now:
//   • the caller must be a signed-in member of the workspace;
//   • test_link loads connectors AS the caller (RLS) and only within that workspace;
//   • every outbound probe goes through net-guard (public http(s) hosts only, DNS
//     checked) and never follows redirects;
//   • per-user rate limit.


type Check = { label: string; ok: boolean; detail?: string };

async function httpProbe(url: string, method = 'HEAD'): Promise<{ ok: boolean; detail: string; latency: number }> {
  const start = Date.now();
  try {
    await assertPublicHttpUrl(url);
  } catch (e) {
    return { ok: false, detail: e instanceof BlockedUrlError ? `Blocked: ${e.message}` : 'Invalid URL', latency: 0 };
  }
  try {
    // redirect: 'manual' — a public URL must not be able to bounce us to an internal one.
    const res = await fetch(url, { method, redirect: 'manual', signal: AbortSignal.timeout(8000) });
    await res.body?.cancel();
    const redirected = res.status >= 300 && res.status < 400;
    return {
      ok: res.status < 500,
      detail: redirected ? `HTTP ${res.status} (redirect not followed)` : `HTTP ${res.status}`,
      latency: Date.now() - start,
    };
  } catch (e) {
    const msg = e instanceof Error ? e.message : 'Request failed';
    return { ok: false, detail: /timed? ?out|abort/i.test(msg) ? 'Timed out after 8s' : 'Could not connect', latency: Date.now() - start };
  }
}

async function testConnectorBody(body: Record<string, unknown>) {
  const start = Date.now();
  const connectorType = String(body.connector_type ?? '');
  const config = (body.config ?? {}) as Record<string, unknown>;
  const checks: Check[] = [];

  if (connectorType === 'rest_api' || connectorType === 'api_push' || connectorType === 'webhook_out') {
    const url = String(config.url ?? '');
    if (!url) {
      checks.push({ label: 'URL', ok: false, detail: 'Missing url' });
    } else {
      try {
        new URL(url);
        checks.push({ label: 'URL format', ok: true, detail: url.slice(0, 200) });
        const probe = await httpProbe(url, connectorType === 'rest_api' ? 'GET' : 'HEAD');
        checks.push({ label: 'HTTP reachability', ok: probe.ok, detail: probe.detail });
      } catch {
        checks.push({ label: 'URL format', ok: false, detail: 'Invalid URL' });
      }
    }
  }

  if (connectorType === 'webhook') {
    checks.push({ label: 'Webhook ready', ok: true, detail: 'Endpoint will accept POST after deploy' });
  }

  if (connectorType === 'sftp') {
    const host = String(config.host ?? '');
    checks.push({ label: 'SFTP host', ok: host.length > 0, detail: host ? `${host}:${config.port ?? 22}` : 'Missing host' });
  }

  if (connectorType === 'database') {
    const cs = String(config.connection_string ?? '');
    checks.push({
      label: 'Connection string',
      ok: cs.startsWith('postgres') || cs.startsWith('mysql'),
      detail: cs ? 'Format OK (live DB ping not enabled)' : 'Missing',
    });
  }

  const failed = checks.filter((c) => !c.ok);
  return {
    status: failed.length ? 'failed' : 'success',
    latency_ms: Date.now() - start,
    message: failed[0]?.detail ?? 'Connection test passed',
    checks,
  };
}

async function testLinkBody(user: AuthedUser, tenantId: string, body: Record<string, unknown>) {
  const sourceId = String(body.source_connector_id ?? '');
  const targetId = String(body.target_connector_id ?? '');
  const bridgeSchema = String(body.bridge_schema ?? '');

  // As the caller (RLS) AND explicitly within the caller's workspace.
  const { data: rows, error } = await user.db.from('connectors')
    .select('id, name, direction, connector_type, config, mapping')
    .eq('tenant_id', tenantId).in('id', [sourceId, targetId]);
  if (error) throw new AuthError(500, 'Could not load connectors');
  const source = rows?.find((r) => r.id === sourceId);
  const target = rows?.find((r) => r.id === targetId);
  if (!source || !target) return errorResponse('Connectors not found', 404);

  const checks: Check[] = [];
  checks.push({ label: 'Source inbound', ok: source.direction === 'inbound', detail: source.direction });
  checks.push({ label: 'Target outbound', ok: target.direction === 'outbound', detail: target.direction });

  const sourceMapping = (source.mapping ?? []) as Array<{ target_schema: string; source_field: string; target_field: string }>;
  const bridgeMaps = sourceMapping.filter((m) => m.target_schema === bridgeSchema && m.source_field && m.target_field);
  checks.push({ label: 'Bridge mappings', ok: bridgeMaps.length > 0, detail: `${bridgeMaps.length} fields` });

  const sourceResult = await testConnectorBody({ connector_type: source.connector_type, config: source.config });
  checks.push({ label: 'Source connection', ok: sourceResult.status === 'success', detail: sourceResult.message });
  const targetResult = await testConnectorBody({ connector_type: target.connector_type, config: target.config });
  checks.push({ label: 'Target connection', ok: targetResult.status === 'success', detail: targetResult.message });

  const failed = checks.filter((c) => !c.ok);
  return jsonResponse({
    status: failed.length ? 'failed' : 'success',
    latency_ms: sourceResult.latency_ms + targetResult.latency_ms,
    message: failed.length ? failed[0].detail : `Link OK: ${source.name} → ${bridgeSchema} → ${target.name}`,
    checks,
  });
}

serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders() });
  if (req.method !== 'POST') return errorResponse('Method not allowed', 405);

  try {
    const user = await authenticateUser(req);
    const body = (await req.json().catch(() => null)) as Record<string, unknown> | null;
    if (!body || typeof body !== 'object') return errorResponse('JSON body required', 400);
    const tenantId = await resolveTenant(user, body.tenant_id);
    if (rateLimited(`connector-test:${user.userId}`, 30)) return errorResponse('Too many tests — wait a minute', 429);

    const action = body.action as string;
    if (action === 'test_connector') return jsonResponse(await testConnectorBody(body));
    if (action === 'test_link') return await testLinkBody(user, tenantId, body);
    return errorResponse('Unknown action', 400);
  } catch (e) {
    if (e instanceof AuthError) return errorResponse(e.message, e.status);
    console.error('connector-test unhandled', e instanceof Error ? e.message : e);
    return errorResponse('Internal error', 500);
  }
});
